window.ScripturaLexicons.BDAG_PART_0350 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-01\" data-source=\"BDAG\" data-search=\"Συχάρ, ἡ topônimo feminino Sicar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Συχάρ, ἡ</td><td>topônimo feminino</td><td>Sicar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-02\" data-source=\"BDAG\" data-search=\"Συχέμ nome próprio indeclinável Siquém (cidade e pessoa) BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Συχέμ</td><td>nome próprio indeclinável</td><td>Siquém (cidade e pessoa)</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-03\" data-source=\"BDAG\" data-search=\"σφαγή, ῆς, ἡ substantivo feminino matança; abate BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφαγή, ῆς, ἡ</td><td>substantivo feminino</td><td>matança; abate</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-04\" data-source=\"BDAG\" data-search=\"σφάγιον, ου, τό substantivo neutro vítima a ser sacrificada; oferenda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφάγιον, ου, τό</td><td>substantivo neutro</td><td>vítima a ser sacrificada; oferenda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-05\" data-source=\"BDAG\" data-search=\"σφάζω verbo abater; trucidar; assassinar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφάζω</td><td>verbo</td><td>abater; trucidar; assassinar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-06\" data-source=\"BDAG\" data-search=\"σφάλλω verbo escorregar; tropeçar; perder BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφάλλω</td><td>verbo</td><td>escorregar; tropeçar; perder</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-07\" data-source=\"BDAG\" data-search=\"σφόδρα advérbio muito; extremamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφόδρα</td><td>advérbio</td><td>muito; extremamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-08\" data-source=\"BDAG\" data-search=\"σφοδρός, α, όν adjetivo excessivo; veemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφοδρός, α, όν</td><td>adjetivo</td><td>excessivo; veemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-09\" data-source=\"BDAG\" data-search=\"σφοδρῶς advérbio muito; violentamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφοδρῶς</td><td>advérbio</td><td>muito; violentamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-10\" data-source=\"BDAG\" data-search=\"σφραγίζω verbo selar; marcar; atestar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφραγίζω</td><td>verbo</td><td>selar; marcar; atestar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-11\" data-source=\"BDAG\" data-search=\"σφραγίς, ῖδος, ἡ substantivo feminino sinete; selo; marca; confirmação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφραγίς, ῖδος, ἡ</td><td>substantivo feminino</td><td>sinete; selo; marca; confirmação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-12\" data-source=\"BDAG\" data-search=\"σφυδρόν, οῦ, τό substantivo neutro tornozelo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφυδρόν, οῦ, τό</td><td>substantivo neutro</td><td>tornozelo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-13\" data-source=\"BDAG\" data-search=\"σφυρίς, ίδος, ἡ remissão ver σπυρίς BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφυρίς, ίδος, ἡ</td><td>remissão</td><td>ver σπυρίς</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-14\" data-source=\"BDAG\" data-search=\"σφυροκοπέω verbo bater com martelo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφυροκοπέω</td><td>verbo</td><td>bater com martelo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-15\" data-source=\"BDAG\" data-search=\"σφυρόν, οῦ, τό substantivo neutro tornozelo; calcanhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σφυρόν, οῦ, τό</td><td>substantivo neutro</td><td>tornozelo; calcanhar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-16\" data-source=\"BDAG\" data-search=\"σχεδόν advérbio aproximadamente; quase BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχεδόν</td><td>advérbio</td><td>aproximadamente; quase</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-17\" data-source=\"BDAG\" data-search=\"σχῆμα, ατος, τό substantivo neutro aparência; forma; modo de vida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχῆμα, ατος, τό</td><td>substantivo neutro</td><td>aparência; forma; modo de vida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-18\" data-source=\"BDAG\" data-search=\"σχηματίζω verbo posicionar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχηματίζω</td><td>verbo</td><td>posicionar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-19\" data-source=\"BDAG\" data-search=\"σχίζω verbo fender; rasgar; dividir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχίζω</td><td>verbo</td><td>fender; rasgar; dividir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0350-20\" data-source=\"BDAG\" data-search=\"σχίσμα, ατος, τό substantivo neutro rasgão; divisão; cisma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σχίσμα, ατος, τό</td><td>substantivo neutro</td><td>rasgão; divisão; cisma</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0350-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Συχάρ, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Συχάρ</span>, <span class=\"greek\">ἡ</span> indecl. Sicar, cidade da Samaria; segundo Jerônimo, Quaest. in Gen. 66, 6 e Epict. 108, 13, uma forma corrompida de <span class=\"greek\">Συχέμ</span> (siríaco sinaítico Shechim); v. artigo seguinte. Muitos estudiosos posteriores rejeitam essa conclusão, geralmente em favor da identificação de Sicar com Askar (samaritano Ischar), no sopé sudeste do monte Ebal. Contudo, as escavações parecem mostrar que Jerônimo tinha razão (v. RB 37, 1928, 619). Um lugar chamado Sichar ou Suchar no Talmude babilônico (Baba Kamma 82b; Menachoth 64b) não pode ser identificado com certeza. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:5</a>.—ESchwartz, NGG 1908, 504f; Zahn, NKZ 19, 1908, 207–18; JBoehmer, ZNW 9, 1908, 218–23; KKundsin, Topolog. Überlieferungsstoffe im Joh. 1925; CKopp, The Holy Places of the Gospels, trad. RWalls ’63, 155–66; BHHW III 1896.—EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Συχέμ</h1><div class=\"entry-meta\"><span>nome próprio indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Συχέμ</span> (<span class=\"hebrew\" dir=\"rtl\">שְׁכֶם</span>) indecl.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> fem., Siquém (<span class=\"greek\">Συχέμ</span> TestLevi 5:3=<span class=\"greek\">Σίκιμα</span> Gen 48:22; Josh 24:32; Demetr.: 722 Fgm. 1, 8 Jac.; Theodotus [II a.C.]: 732 Fgm. 1 p. 692, 23 al. Jac. [em Eus., PE 9, 22, 2]; Joseph.), cidade da Samaria, destruída em 128 a.C. por Hircano I. A oeste dela, Vespasiano fundou uma nova cidade, Flavia Neapolis (Eus., Onom. p. 150, 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:16a</a>b.—KBaedeker, Pal. u. Syr.7 1910, 203ff; FFörster, Sichem, s. Gesch. u. Bed., diss. Leipzig 1923; vários artigos ZDPV 1926–28; ESellin (material anterior em PThomsen, Palätina u. s. Kultur3 ’31, 116): ZAW 50, ’32, 303–8; PThomsen, Reallex. d. Vorgesch. XII 1928, 74ff; TBöhl, De opgraving van Sichem 1927; GWright em BASOR ’56–’62, The Biography of a Bibl. City ’65; ENielsen, Shechem, A Traditio-Hist. Investigation ’55; BHHW III, 1781–83; Kl. Pauly V 163.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> masc., um filho de Hamor, Siquém (v. <span class=\"greek\">Ἑμμώρ</span>) <span class=\"greek\">Ἑμμὼρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Συχέμ</span> (cf. Gen 33:19; JosAs 23:13) Hamor, pai de Siquém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:16</a> v.l. (em Jos., Ant. 1, 337f <span class=\"greek\">Συχέμμης</span>).—M-M. EDNT.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφαγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφαγή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">σφάζω</span>; Trag., X., Pla. et al.; LXX; En 16:1; PsSol 8:1; TestSol 17:1; Philo; Jos., Ant. 1, 102; 7, 39; Ar. 8, 6 [G]; Mel., P. 3, 17 al.; Ath. 14, 1) matança, abate <span class=\"greek\">πρόβατα</span> <span class=\"greek\">σφαγῆς</span> ovelhas destinadas ao abate (cf. Zech 11:4, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:36</a> (Ps 43:23). <span class=\"greek\">προσφέρειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σφαγήν</span> levar para ser morto B 8:2. Pass. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σφ</span>. <span class=\"greek\">ἄγεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:32</a>; 1 Cl 16:7; B 5:2 (em cada caso Is 53:7. Cf. Lucian, Dem. 40 a pergunta <span class=\"greek\">βοῦν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σφαγὴν</span> <span class=\"greek\">ἤγομεν</span>; em linguagem figurada com referência a Demosth.). <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">σφαγῆς</span> dia da matança (Jer 12:3; En 16:1; cf. Syntipas p. 13, 1 <span class=\"greek\">ἡμέρα</span> … <span class=\"greek\">τ</span>. <span class=\"greek\">σφαγῆς</span>.—<span class=\"greek\">σφ</span>.=massacre, banho de sangue: Appian, Bell. Civ. 2, 24 §91) do Dia do Juízo (Beyschlag, Spitta, FHauck, Meinertz et al.) ou de um dia de infortúnio, quando as coisas correram mal para os pobres, mas não para os ricos (Windisch, MDibelius) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:5</a> (‘dia da matança’, no sentido de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.24\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:24</a>; <span class=\"greek\">σφ</span>. com referência a seres humanos: Diod S 13, 48, 1; 8).—DELG s.v. <span class=\"greek\">σφάζω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφάγιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφάγιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">σφαγή</span>; Aeschyl., Hdt.+; LXX, Philo; Jos., Bell. 6, 434) algo oferecido em sacrifício, vítima a ser sacrificada, oferenda pl. (com <span class=\"greek\">θυσίαι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:42</a> (Am 5:25).—DELG s.v. <span class=\"greek\">σφάζω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφάζω</span> fut. <span class=\"greek\">σφάξω</span>; 1 aor. <span class=\"greek\">ἔσφαξα</span>. Pass. 2 fut. 3 pl. <span class=\"greek\">σφαγήσονται</span> Num 11:22; 2 aor. 2 sg. <span class=\"greek\">ἐσφάγης</span>, 3 pl. <span class=\"greek\">ἐσφάγησαν</span> (Ar. 13, 6), part. <span class=\"greek\">σφαγείς</span> (LXX, Mel.), inf. <span class=\"greek\">σφαγῆναι</span> (Is 14:21; Ar. 10, 8); perf. part. <span class=\"greek\">ἐσφαγμένος</span> (Hom. et al. [ático <span class=\"greek\">σφάττω</span>; Tat. 10, 2; Ath. 1, 3; v. B-D-F §71; Mlt-H. 404]; inscr., pap., LXX; pseudepígr., apolog.; Orig., C. Cels. 6, 35, 26; Theoph. Ant.) abater com acus. <span class=\"greek\">ἀρνίον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:6</a>, 12; 13:8 (em todas essas passagens pass., <span class=\"greek\">ἀρνίον</span> <span class=\"greek\">ἐσφαγμένον</span>). Abs. B 8:1. Da morte violenta de uma pessoa (Pind. et al.; Theoph. Ant. 3, 5 [p. 214, 1]) <span class=\"greek\">σφάζειν</span> <span class=\"greek\">τινά</span> trucidar ou assassinar alguém (4 Km 10:7; Jer 52:10; Manetho: 609 Fgm. 8, 76 Jac. [em Jos., C. Ap. 1, 76]; Demetr. [?]: 722 Fgm. 7; Ar. 10, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:4</a>. Pass. (Hdt. 5, 5) 5:9; 6:9; 18:24. <span class=\"greek\">κεφαλὴ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐσφαγμένη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">θάνατον</span> uma cabeça que parecia estar mortalmente ferida 13:3.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφάλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφάλλω</span> fut. 3 pl. <span class=\"greek\">σφαλοῦσιν</span> 2 Km 22:46; 1 aor. 3 sg. <span class=\"greek\">ἔσφαλε</span> LXX. Pass. 2 fut. <span class=\"greek\">σφαλήσομαι</span>; 2 aor. 3 pl. <span class=\"greek\">ἐσφάλησαν</span> (LXX; AcPl Ha 8, 20) (Hom. et al.; PGM 36, 221; LXX, Philo; Jos., Bell. 3, 479, Ant. 7, 264; Just., A I, 43, 4) em nossa literatura somente pass., sentido ativo</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> perder o apoio dos pés, escorregar, tropeçar, cair, lit. (Aristoph., Vesp. 1324; X., Lac. 5, 7; Diod S 3, 24, 3; Maximus Tyr. 21, 2b; 34, 2e; Dt 32:35) pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:14</a> v.l.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> deixar de obter algo que se esperava, perder a oportunidade de obter com gen. (Aeschyl., Soph., Eur., Thu.) <span class=\"greek\">ἐσφάλησαν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κληρονομίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">αἰωνίας</span> perderam sua herança eterna AcPl Ha 8, 20f=Ox 1602, 27f//BMM recto 26f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφόδρα</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφόδρα</span> adv. de <span class=\"greek\">σφοδρός</span> (Pind., Hdt. et al.) um ponto muito elevado numa escala de intensidade, muito, extremamente, grandemente (em muitos contextos com referência à veemência ou à violência) usado com adj. (Lucian, Nigr. 37; PEdg 11 [= Sb 6717], 6 [257 a.C.]; pseudepígr.; Jos., Vi. 191; Tat. 32, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:10</a>; 14:30 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:21</a>; GJs 1:1. Usado com verbos (Aeneas Tact. 1463; TestBenj 1:5; TestAbr A 20 p. 103, 14 [Stone p. 54] e B 3 p. 108, 5 [Stone p. 64]; JosAs 8:8f; 24:12 <span class=\"greek\">ἐταράχθησαν</span> <span class=\"greek\">σφόδρα</span>; Jos., Vi. 159 <span class=\"greek\">ἐταράχθην</span> <span class=\"greek\">σφόδρα</span>; Just., D. 2, 6; Herm. Wr. 1, 1) <span class=\"greek\">φοβεῖσθαι</span> <span class=\"greek\">σφ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:6</a>; 27:54; GJs 14:1. <span class=\"greek\">λυπεῖσθαι</span> (1 Macc 14:16; JosAs 8:8; ParJer 9:23; GrBar 12:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:23</a>; 18:31; 26:22; GJs 1:3f; 2:4; AcPl Ha 7, 16. <span class=\"greek\">ἐκπλήττεσθαι</span> 19:25. <span class=\"greek\">πληθύνεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:7</a>. <span class=\"greek\">ἐταπείνωσεν</span> … <span class=\"greek\">σφ</span>. GJs 2:3; <span class=\"greek\">εὐλόγησέν</span> <span class=\"greek\">με</span> <span class=\"greek\">σφ</span>. 4:4; <span class=\"greek\">ἠνόμησεν</span> … <span class=\"greek\">σφ</span>. 15:2.—DELG s.v. <span class=\"greek\">σφεδανός</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφοδρός, α, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφοδρός</span>, <span class=\"greek\">α</span>, <span class=\"greek\">όν</span> (Thu., Pla, X.; LXX; TestNapht 6:4; TestSol 10:37 C) relativo ao que é excessivo, veemente (v. artigo precedente) <span class=\"greek\">χάλαζα</span> … <span class=\"greek\">λίαν</span> <span class=\"greek\">μεγάλην</span> (leia-se: <span class=\"greek\">μεγάλη</span>) <span class=\"greek\">σφοδρά</span> uma violenta tempestade de granizo AcPl Ha 5, 7.—DELG s.v. <span class=\"greek\">σφεδανός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφοδρῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφοδρῶς</span> adv. (Hom. et al.; Aelian, NA 14, 26 p. 359, 23; SIG 1169, 57; LXX; Jos., Ant. 13, 292 al.) muito, grandemente, violentamente (v. os dois artigos precedentes) <span class=\"greek\">σφ</span>. <span class=\"greek\">χειμάζεσθαι</span> ser violentamente açoitado por uma tempestade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:18</a> (cf. Jos., Ant. 14, 377 <span class=\"greek\">χειμῶνι</span> <span class=\"greek\">σφοδρῷ</span> <span class=\"greek\">περιπεσών</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφραγίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφραγίζω</span> 1 aor. <span class=\"greek\">ἐσφράγισα</span>. Méd.: fut. 2 sg. <span class=\"greek\">σφραγιῇ</span> Jer 39:44; 1 aor. <span class=\"greek\">ἐσφραγισάμην</span>. Pass.: 1 aor. <span class=\"greek\">ἐσφραγίσθην</span>; perf. part. <span class=\"greek\">ἐσφραγισμένος</span> (v. artigo seguinte; Aeschyl. et al.; inscr., pap., LXX, TestSol; TestJob 5:2; ParJer 3:10; ApcMos 42; Philo, Joseph.; Mel., P. 15, 97 al.)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> munir de um selo como medida de segurança, selar com acus. do objeto que deve ser assegurado ou fixado pelo selo: de uma pedra, para impedir que seja removida de sua posição (Da 6:18=Jos., Ant. 10, 258) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.66\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:66</a> (mas v. <span class=\"greek\">μετά</span> A3b). Igualmente GPt 9:34, onde as palavras <span class=\"greek\">μνημεῖον</span> <span class=\"greek\">ἐσφραγισμένον</span> remetem à selagem da pedra usada para fechar o túmulo (8:32f); cf. ApcMos 42 <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> … <span class=\"greek\">ἐσφράγισε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μνημεῖον</span>. No caso de um edifício fechado, para que não possa ser aberto (Bel 11; 14) <span class=\"greek\">τὰς</span> <span class=\"greek\">κλεῖδας</span> 1 Cl 43:3. Um feixe de varas que não deviam ser mexidas 43:2. Abs. <span class=\"greek\">ἐσφράγισεν</span> <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">αὐτοῦ</span> selou (a boca fechada do abismo) sobre ele <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:3</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> fechar algo hermeticamente, selar <span class=\"greek\">τὶ</span> algo a fim de mantê-lo em segredo (Solon em Stob., Flor. III p. 114, 8 H. <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">σιγῇ</span>; Cleopatra 73 <span class=\"greek\">μυστήριον</span> <span class=\"greek\">ἐσφραγισμένον</span>; PTebt 413, 6; Job 14:17; 24:16; Da 9:24 Theod.; Da 12:9 LXX) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:4</a>; 22:10.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> marcar com um selo como meio de identificação, marcar, selar (Eur., Iph. T. 1372; Mel., P. 16, 104 al.; nos pap., de toda espécie de animais), de modo que a marca que denota propriedade traz consigo também a proteção do proprietário (quanto ao aspecto apotropaico, cf. TestSol 14:2): <span class=\"greek\">σφραγίσωμεν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">δούλους</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μετώπων</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:3</a> (marcação com um selo na fronte no culto de Mitra: Tertullian, Praescr. Haer. 40). Correspondentemente <span class=\"greek\">ἐσφραγισμένοι</span> vs. 4ab, 5, 8 (quanto ao conceito de selagem escatológica, cf. Ezk 9:4ff; Is 44:5; PsSol 15:6, 9; 4 Esdr 6:5f; 8:51ff. V. também LBrun, Übriggebliebene u. Märtyrer in Apk: StKr 102, 1930, 215–31). Isso constitui uma base para compreender a linguagem figurada que fala dos que ingressam na comunidade cristã como sendo selados com ou pelo Espírito Santo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:13</a>; cf. 4:30. Semelhantemente <span class=\"greek\">θεός</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">σφραγισάμενος</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δοὺς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀρραβῶνα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">καρδίαις</span> <span class=\"greek\">ἡμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:22</a>; mas aqui o contexto contribui com um componente adicional no sentido de ‘dotar de poder do céu’, como claramente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:27</a> (cf. <span class=\"greek\">σφραγίς</span> 4a); mas EDinkler, OCullmann Festschr. ’62, 183–88 associa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:22</a> ao batismo; v. <span class=\"greek\">σφραγίς</span> 4b.</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> certificar que algo é assim, atestar, certificar, reconhecer, fig. (como faz um selo num documento: pap.; Jer 39:10f; Esth 8:8, 10.—Anth. Pal. 9, 236 <span class=\"greek\">ἐσφράγισαν</span> <span class=\"greek\">ὅρκοι</span>) seguido de <span class=\"greek\">ὅτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.33\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:33</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">⑤</span> selar algo para entrega, selar <span class=\"greek\">σφραγισάμενος</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">καρπὸν</span> <span class=\"greek\">τοῦτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:28</a> deve talvez ser compreendido a partir da prática de selar sacos de cereais (Dssm., NB 65f [BS 238f]). Mas alguns julgaram que a imagem é bastante difícil de sustentar, uma vez que o ‘fruto’ deve não somente ser selado, mas também remetido a Jerusalém e ali entregue. Em todo caso, o sentido da expressão é mais fácil de compreender em formulação semelhante a esta: quando eu tiver depositado com segurança (selado) em suas mãos a soma arrecadada (v. LRadermacher, ZNW 32, ’33, 87–89; HBartsch, ZNW 63, ’72, 95–107). Sobre o debate v. New Docs 2, 191, com um papiro tardio em apoio adicional à opinião de Dssm.—Straub 29f. DELG s.v. <span class=\"greek\">σφραγίς</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφραγίς, ῖδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφραγίς</span>, <span class=\"greek\">ῖδος</span>, <span class=\"greek\">ἡ</span> (v. artigo precedente; Trag., Hdt.+; inscr., pap., LXX; PsS 2:6; TestPs, ParJer; ApcMos 42; Philo; Jos., Ant. 15, 408; 18, 93 al.; empréstimo na literatura rabínica) primariamente ‘selo, sinete’.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> instrumento usado para selar ou estampar, sinete (Aristot., Strabo et al., Appian, Liby. 32 §137; 104 §493, Bell. Civ. 2, 22 §82; pap., LXX; Hippol., Ref. 9, 11, 5) <span class=\"greek\">σφραγὶς</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:2</a> (contra o poder dos demônios etc. RCharles, Comm. I 196).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> substância que traz a impressão de um sinete e sela um documento, selo (ParJer 3:10) GPt 8:33; 1 Cl 43:5. Em Rv um livro com sete selos 5:1 (um testamento de última vontade segundo EHuschke, Das Buch mit sieben Siegeln 1860, Zahn, JWeiss; cf. JMarquardt, Römisches Privatieben2 1886, 805f; TBirt, Die Buchrolle in der Kunst 1907, 243.—Sobre Rv 5f: WSattler, ZNW 20, 1921, 231–40; 21, 1922, 43–53; KStaritz, ibid. 30, ’31, 157–70; WTaylor, JTS 31, 1930, 266–71). <span class=\"greek\">λῦσαι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">σφραγῖδας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:2</a>, 5 v.l. (cf. <span class=\"greek\">λύω</span> 1a). Também <span class=\"greek\">ἀνοῖξαι</span> vs. 5, 9; 6:1, 3, 5, 7, 9, 12 (Aeschyl., Eum. 828); 8:1 (<span class=\"greek\">ἀνοίγω</span> 4).</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> impressão feita por um sinete, marca (Hdt. et al.; LXX; ApcMos 42) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:4</a> (cf. Martial 3, 21, de um escravo ‘fronte notata’). Em linguagem figurada <span class=\"greek\">ὁ</span> <span class=\"greek\">θεμέλιος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σφραγῖδα</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">κτλ</span>. o fundamento de Deus que traz a seguinte marca (=inscrição) … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:19</a> (v. Dölger, Sphragis 3; Straub 63).—Cf. Hs 8, 2, 4, provavelmente de um documento que traz uma marca que permite a passagem, um salvo-conduto (cf. Aberciusins. 9 <span class=\"greek\">λαὸς</span> <span class=\"greek\">λαμπρὰν</span> <span class=\"greek\">σφραγεῖδαν</span> <span class=\"greek\">ἔχων</span> e o hino naasseno em Hippol., Ref. 5, 10, 2 <span class=\"greek\">σφραγῖδας</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">καταβήσομαι</span>; igualmente os livros de Jeû e os escritos mandeus; Mani, Kephal. I 225, 13; 15; 18; diferentemente Leutzsch, Hermas p. 480 n. 201).</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> aquilo que confirma ou autentica, atestação, confirmação, certificação, extensão fig. de 3</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> com o gen. daquilo que é confirmado ou autenticado <span class=\"greek\">ἡ</span> <span class=\"greek\">σφραγίς</span> <span class=\"greek\">μου</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀποστολῆς</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">ἐστε</span> vós sois a certificação do meu apostolado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:2</a>. <span class=\"greek\">σημεῖον</span> <span class=\"greek\">ἔλαβεν</span> <span class=\"greek\">περιτομῆς</span> <span class=\"greek\">σφραγῖδα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δικαιοσύνης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> ele (Abraão) recebeu o sinal da circuncisão como algo que confirma a justiça pela fé que já estava presente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:11</a>. <span class=\"greek\">σφ</span>. não precisa ser mais que uma metáfora de atestação ou confirmação em <span class=\"greek\">περιτέτμηται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λαὸς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">σφραγῖδα</span> B 9:6.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> como termo para batismo em 2 Cl e Hermas (Theognis linha 19: o nome do autor, como uma <span class=\"greek\">σφρηγίς</span> [forma jônica], protege sua obra contra toda possibilidade de falsificação): <span class=\"greek\">ἡ</span> <span class=\"greek\">σφραγίς</span> 2 Cl 7:6; 8:6; Hs 8, 6, 3; 9, 16, 3ff al. <span class=\"greek\">ἡ</span> <span class=\"greek\">σφ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Hs 9, 16, 3 (também AcThom 131 [Aa II/2, 239, 3; v. Leutzsch, Hermas p. 483 n. 239]. Cf. <span class=\"greek\">ἡ</span> <span class=\"greek\">σφ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> Clem. Alex., Quis Div. Salv. 42, 4. <span class=\"greek\">ἡ</span> <span class=\"greek\">σφ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> AcPh 134 [Aa II/2, 65, 11]; <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">σφραγῖδος</span> AcPl Ha 3, 24; 11, 23 [v. <span class=\"greek\">μυέω</span>]; <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">σφ</span>. AcPlTh 25 [Aa I, 253, 7f]; AcThom, final [Aa II/2, 291, 7f]). Usado com os verbos <span class=\"greek\">διδόναι</span> <span class=\"greek\">τινὶ</span> (<span class=\"greek\">τὴν</span> <span class=\"greek\">σφ</span>.) Hs 9, 16, 5b (AcThom 49 [Aa II/2, 165, 14]; v. também 27 [Aa II/2, 142f]). <span class=\"greek\">λαμβάνειν</span> 8, 6, 3; 9, 16, 3; 9, 17, 4. <span class=\"greek\">ἔχειν</span> 9, 16, 5a; 7; <span class=\"greek\">κηρύσσειν</span> 9, 16, 4b. <span class=\"greek\">τεθλακέναι</span> 8, 6, 3. <span class=\"greek\">τηρεῖν</span> 2 Cl 7:6; 8:6= <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βάπτισμα</span> 6:9 (<span class=\"greek\">δέχεσθαι</span> AcThom 26 [Aa II/2, 141, 14]; <span class=\"greek\">περιτιθέναι</span> Celsus em Origen, C. Cels. 2, 96f).—GAnrich, Das Antike Mysterienwesen 1894, 120ff; GWobbermin, Religionsgesch. Studien 1896, 144ff; ASeeberg, Der Katechismus der Urchristenheit 1903, 232ff; FDölger, Sphragis als Taufbez. 1911, 49ff, Ac I 1929, 88–91; AvStromberg, Studien zur Theorie u. Praxis der Taufe 1913, 89ff; WHeitmüller, <span class=\"greek\">ΣΦΡΑΓΙΣ</span>: Heinrici Festschr. 1914, 40ff; WBousset, Kyrios Christos2 1921, 227ff; FPreisigke, Die Gotteskraft der frühchristl. Zeit 1922, 25f; EMaass, Segnen, Weihen, Taufen: ARW 21, 1922, 241ff; JYsebaert, Greek Baptismal Terminol., ’62, 204f.—Kl. Pauly V 309; OEANE IV 509–12; DBS XII 66–228 esp. 213–28 sobre o NT; BHHW III 1786–90.—DELG. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφυδρόν, οῦ, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφυδρόν</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">τό</span> (PFlor 391, 53; 56 [III d.C.]; Hesych.) tornozelo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:7</a> (v.l. <span class=\"greek\">σφυρόν</span>, q.v.; B-D-F §34, 6).—DELG s.v. <span class=\"greek\">σφυρόν</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφυρίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφυρίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> v. <span class=\"greek\">σπυρίς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφυροκοπέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφυροκοπέω</span> (<span class=\"greek\">σφῦρα</span> ‘martelo’, cf. <span class=\"greek\">κόπτω</span> ‘golpear’; Philod., <span class=\"greek\">Περὶ</span> <span class=\"greek\">σημείων</span> 2, 7 Gomp.; Judg 5:26 B) bater com um martelo <span class=\"greek\">τὶ</span> algo, de um ferreiro <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">αὐτοῦ</span> seu trabalho Hv 1, 3, 2.—DELG s.v. <span class=\"greek\">σφῦρα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σφυρόν, οῦ, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σφυρόν</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">τό</span></p><p class=\"entry-text\"><span class=\"sense-number\">①</span> tornozelo (Hom. et al.; EpArist 87; Jos., Ant. 3, 155; 7, 171).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> calcanhar (Eur., Alc. 586; Ps.-Oppian, Cyn. 3, 143); ambos são possíveis em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:7</a> v.l. V. <span class=\"greek\">σφυδρόν</span>.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχεδόν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχεδόν</span> adv. (Hom. et al.) aproximadamente, quase (Soph., X., Pla.; inscr., pap.; 2 Macc 5:2; 3 Macc 5:14, 45; EpArist, Philo, Just.; Tat. 41, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:44</a> (cf. Jos., Ant. 7, 20 <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">σχεδόν</span>); 19:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:22</a> (cf. Jos., Ant. 1, 18 <span class=\"greek\">πάντα</span> <span class=\"greek\">σχ</span>.); B 16:2; MPol 1:1; 22:3; EpilMosq 5.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχῆμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχῆμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (da mesma raiz que <span class=\"greek\">ἔχω</span>, cf. 2 aor. inf. <span class=\"greek\">σχεῖν</span>; Aeschyl., Thu.+; empréstimo na literatura rabínica; em vários sentidos ‘porte, maneira, comportamento’, cf. lat. ‘habitus’)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> estado ou forma geralmente reconhecidos em que algo se apresenta, aparência exterior, forma, figura de pessoa Hv 5:1 (Menyllus: 295 Fgm. 2 Jac. <span class=\"greek\">Ἄρης</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σχήματι</span> <span class=\"greek\">ποιμένος</span>). <span class=\"greek\">σχήματι</span> <span class=\"greek\">εὑρεθεὶς</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ἄνθρωπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:7</a> (Just., A I, 55, 4 <span class=\"greek\">ἀνθρώπειον</span> <span class=\"greek\">σχῆμα</span>; cf. Lucian, Somn. 13 <span class=\"greek\">ἀφεὶς</span> … <span class=\"greek\">τιμὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δόξαν</span> … <span class=\"greek\">κ</span>. <span class=\"greek\">δύναμιν</span> <span class=\"greek\">σχῆμα</span> <span class=\"greek\">δουλοπρεπὲς</span> <span class=\"greek\">ἀναλήψῃ</span>; Jos., Ant. 10, 11 um rei que troca suas vestes reais por pano de saco e assume um <span class=\"greek\">σχῆμα</span> <span class=\"greek\">ταπεινόν</span>; quanto a <span class=\"greek\">σχῆμα</span> <span class=\"greek\">ταπεινόν</span>, cf. também Appian, Syr. 40 §206; quanto à associação de <span class=\"greek\">σχῆμα</span> e <span class=\"greek\">ὄνομα</span>, cf. Cass. Dio 42, 24).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> aspecto funcional de algo, modo de vida, de coisas (Just., D. 105, 2 al. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταυροῦ</span>) <span class=\"greek\">παράγει</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σχῆμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">τούτου</span> este mundo em sua forma presente está passando <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:31</a> (Eur., Bacch. 832 <span class=\"greek\">τὸ</span> <span class=\"greek\">σχ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>; Philostrat., Vi. Apoll. 8, 7 p. 312, 9 <span class=\"greek\">τὸ</span> <span class=\"greek\">σχ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">τοῦδε</span>; PGM 4, 1139 <span class=\"greek\">σχῆμα</span> <span class=\"greek\">κόσμου</span>). V. <span class=\"greek\">μορφή</span>.—B. 874. DELG s.v. <span class=\"greek\">ἔχω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχηματίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχηματίζω</span> aor. <span class=\"greek\">ἐσχημάτισα</span> (v. artigo precedente; Hippocr., Pla., POxy 2267, 13 [IVd.C.], Philo, Just.—Geralmente ‘dar forma’ a algo, daí ‘preparar’ para algo) fazer com que esteja em posição apropriada para algo, posicionar (quanto ao uso frequente de <span class=\"greek\">ς</span>. em referência à postura, v. L-S-J-M) <span class=\"greek\">ἐσχημάτισεν</span> <span class=\"greek\">αὐτήν</span> (Salomé) posicionou (Maria) para um exame de sua virgindade GJs 20:1 pap.; diferentemente códices: <span class=\"greek\">σχημάτισον</span> <span class=\"greek\">σαυτήν</span> põe-te em posição (dito pela parteira), seguido da ação de Maria <span class=\"greek\">ἐσχημάτισεν</span> <span class=\"greek\">αὑτήν</span> (para o exame de Salomé).—DELG s.v. <span class=\"greek\">ἔχω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχίζω</span> fut. <span class=\"greek\">σχίσω</span>; 1 aor. <span class=\"greek\">ἔσχισα</span>. Pass.: fut. 3 sg.; aor. <span class=\"greek\">ἐσχίσθην</span>; perf. part. pl. <span class=\"greek\">ἐσχισμένοι</span> Is 36:22 (Hom. Hymns et al.; pap., LXX, Test12Patr; JosAs 14:3; ParJer 2:5; Philo; Jos., Ant. 8, 207; 20, 97)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> dividir mediante o emprego de força, fender, dividir, separar, rasgar, arrancar lit. <span class=\"greek\">τὶ</span> algo</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> ativo <span class=\"greek\">τὸ</span> <span class=\"greek\">ξύλον</span> fender a madeira (Antig. Car. 142 <span class=\"greek\">ξύλον</span> <span class=\"greek\">σχίσας</span>; Paradoxogr. Flor. 9; Paroem. Gr.: Apostolius 7, 24a) Ox 1 recto, 8 (GTh 77; cf. Eccl 10:9, também Gen 22:3; 1 Km 6:14 e v. <span class=\"greek\">ἐγείρω</span> 10). <span class=\"greek\">τὸ</span> <span class=\"greek\">καινὸν</span> <span class=\"greek\">σχίσει</span> rasgará o novo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36b</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:24</a>. <span class=\"greek\">ἐπίβλημα</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἱματίου</span> <span class=\"greek\">σχ</span>. rasgar (arrancando) um remendo de uma veste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:36a</a> (cf. Jos., Ant, 8, 207).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> pass. ser dividido, ser rasgado, ser fendido <span class=\"greek\">αἱ</span> <span class=\"greek\">πέτραι</span> <span class=\"greek\">ἐσχίσθησαν</span> as rochas foram fendidas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:51b</a> (cf. Is 48:21; TestLevi 4:1; PTebt 273, 43; 52 <span class=\"greek\">λίθος</span> <span class=\"greek\">σχισθείς</span>). Da cortina no templo (v. <span class=\"greek\">καταπέτασμα</span>) <span class=\"greek\">ἐσχίσθη</span> (ela) foi rasgada (cf. Anacr. 95b Diehl; como portento, cf. Plut., Dem. 894 [12, 3] da veste de Atena, que foi rasgada [<span class=\"greek\">ἐρράγη</span>] durante uma procissão) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:45</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">δύο</span> (cf. escólio a Apollon. Rhod. 4, 282–91b p. 281, 10 W. <span class=\"greek\">σχίζεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δύο</span>; Polyb. 2, 16, 11 <span class=\"greek\">εἰς</span> <span class=\"greek\">δύο</span> <span class=\"greek\">μέρη</span>; PGM 13, 262 <span class=\"greek\">σχίσον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">δύο</span>=em dois) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:51a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:38</a> (D + <span class=\"greek\">μέρη</span>). De uma rede <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:11</a>. Da abóbada celeste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:10</a> (JosAs 14:4 <span class=\"greek\">ἐσχίσθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρανός</span>; Himerius, Or. [Ecl.] 32, 14 <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">σχίσας</span> para um anúncio divino, para trazer da casa de Zeus uma alma pura, <span class=\"greek\">τῶν</span> <span class=\"greek\">θείων</span> <span class=\"greek\">φασμάτων</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οὐσίαν</span> <span class=\"greek\">διαπορθμεύουσαν</span>=que nos comunica a natureza das aparições divinas).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> desagregar um grupo por meio de propósitos ou objetivos conflitantes, extensão fig. de 1</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> ativo causar uma divisão/cisma IPhld 3:3 (cf. Dionys. Alex. em Eus., HE 6, 45).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> pass. tornar-se dividido/desunido (X., Symp. 4, 59 <span class=\"greek\">ἐσχίσθησαν</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μὲν</span> …, <span class=\"greek\">οἱ</span> <span class=\"greek\">δέ</span>) <span class=\"greek\">ἐσχίσθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πλῆθος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:4</a>; 23:7 (cf. Diod S 12, 66, 2 <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλήθους</span> <span class=\"greek\">σχιζομένου</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αἵρεσιν</span>; Celsus 3, 10; Ps.-Lucian, Asin. 54 <span class=\"greek\">εἰς</span> <span class=\"greek\">δύο</span> <span class=\"greek\">γνώμας</span>).—B. 564; 845. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0350-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σχίσμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σχίσμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span>(<span class=\"greek\">σχίζω</span>; Aristot. et al.; ‘fenda, divisão’)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> condição resultante de fender ou rasgar, rasgão, rachadura (Aristot., HA 2, 1; Physiogn. I 372, 6; En 1:7) numa veste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:21</a>; numa vara Hs 8, 5, 1; numa pedra 9, 8, 3.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> condição de estar dividido por causa de propósitos ou objetivos conflitantes, divisão, dissensão, cisma, extensão fig. de 1 (PLond 2710 recto, 13 [=Sb 7835—I a.C.] o <span class=\"greek\">ἡγούμενος</span> da irmandade de Zeus Hypsistos proíbe <span class=\"greek\">σχίσματα</span> com o máximo rigor; Cat. Cod. Astr. XI/2 p. 122, 24 <span class=\"greek\">πολέμους</span>, <span class=\"greek\">φόνους</span>, <span class=\"greek\">μάχας</span>, <span class=\"greek\">σχίσματα</span>; Hippol., Ref. 6, 35, 5 com <span class=\"greek\">διαφορά</span>; Iren. 4, 33, 7 [Harv. II 261, 1], oposto: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἕνωσις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκκλησίας</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.43\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:43</a>; 9:16; 10:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:10</a>; 11:18; 12:25; 1 Cl 46:9; 49:5 (<span class=\"greek\">ἔσονται</span> <span class=\"greek\">σχίσματα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αἱρέσεις</span> Just., D. 35, 3 [citação evangélica de origem desconhecida; v. Unknown Sayings 59–61]). Com <span class=\"greek\">στάσις</span> 2:6; com <span class=\"greek\">στάσις</span>, <span class=\"greek\">ἔρις</span> 54:2. <span class=\"greek\">ἔρεις</span>, <span class=\"greek\">θυμοί</span>, <span class=\"greek\">διχοστασίαι</span>, <span class=\"greek\">σχίσματα</span>, <span class=\"greek\">πόλεμος</span> 46:5. <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">σχίσμα</span> causar uma divisão D 4:3; B 19:12. <span class=\"greek\">σχίσματα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">ἐποίησαν</span> ocasionaram divisões (de opinião) em suas próprias mentes (ou entre si; v. <span class=\"greek\">ἑαυτοῦ</span> 2) Hs 8, 9, 4.—MMeinertz, BZ n.s. 1, ’57, 114–18.—M-M. DELG s.v. <span class=\"greek\">σχίζω</span>. TW. Sv.</p></section></article>"};
